Apply Tailwind CSS to {{componentName}}.

**Condition**: Only execute if {{stylingApproach}} is 'tailwind'

**Input**: Read component at {{componentPath}} and STYLING_SPEC.md

**Your Task**: Update the component to use Tailwind classes.

**Tailwind Best Practices**:

### 1. Use Utility Classes

```tsx
export function {{componentName}}() {
  return (
    <div className="flex flex-col gap-4 p-6 bg-white border border-gray-200 rounded-lg shadow-sm transition-all hover:shadow-md">
      <h2 className="text-xl font-semibold text-gray-900">
        Title
      </h2>

      <div className="flex-1 text-gray-600">
        Content
      </div>

      <div className="flex justify-end gap-2 pt-4 border-t border-gray-200">
        <button className="px-4 py-2 text-sm font-medium text-white bg-blue-600 rounded-md hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed">
          Action
        </button>
      </div>
    </div>
  );
}
```

### 2. Extract Complex Classes to Helper Function

```tsx
import { clsx } from 'clsx';
import { twMerge } from 'tailwind-merge';

function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

interface ButtonProps {
  variant?: 'primary' | 'secondary';
  size?: 'sm' | 'md' | 'lg';
}

const buttonVariants = {
  primary: 'bg-blue-600 text-white hover:bg-blue-700',
  secondary: 'bg-gray-200 text-gray-900 hover:bg-gray-300',
};

const buttonSizes = {
  sm: 'px-3 py-1.5 text-sm',
  md: 'px-4 py-2 text-base',
  lg: 'px-6 py-3 text-lg',
};

export function Button({ variant = 'primary', size = 'md', ...props }: ButtonProps) {
  return (
    <button
      className={cn(
        'rounded-md font-medium transition-colors',
        'focus:outline-none focus:ring-2 focus:ring-offset-2',
        'disabled:opacity-50 disabled:cursor-not-allowed',
        buttonVariants[variant],
        buttonSizes[size]
      )}
      {...props}
    />
  );
}
```

### 3. Responsive Classes

```tsx
<div className="
  flex flex-col gap-4 p-4
  sm:flex-row sm:gap-6 sm:p-6
  lg:max-w-4xl lg:mx-auto
">
  {/* Content */}
</div>
```

### 4. Dark Mode

```tsx
<div className="
  bg-white text-gray-900
  dark:bg-gray-900 dark:text-white
">
  {/* Content */}
</div>
```

### 5. Custom Animations

In `tailwind.config.js`:
```js
module.exports = {
  theme: {
    extend: {
      animation: {
        'fade-in': 'fadeIn 0.3s ease-in-out',
      },
      keyframes: {
        fadeIn: {
          '0%': { opacity: '0' },
          '100%': { opacity: '1' },
        },
      },
    },
  },
};
```

Then use:
```tsx
<div className="animate-fade-in">
  {/* Content */}
</div>
```

**Common Tailwind Patterns**:

- Flexbox: `flex flex-col/flex-row items-center justify-between gap-4`
- Grid: `grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4`
- Spacing: `p-4 px-6 py-3 m-4 mt-6`
- Colors: `bg-blue-600 text-white border-gray-200`
- Typography: `text-base font-medium leading-relaxed`
- Borders: `border border-gray-200 rounded-lg`
- Shadows: `shadow-sm shadow-md shadow-lg`
- Transitions: `transition-all duration-200 ease-in-out`

